package dev.zomboid.gore;import net.minecraft.world.entity.monster.Zombie;import net.minecraft.network.syncher.SynchedEntityData;import com.tacz.guns.api.TimelessAPI;import net.minecraft.nbt.CompoundTag;
public class Checks{static int n;static void check(boolean b){if(!b)throw new AssertionError("check "+n);n++;}public record Event(Object entity){public Object getEntity(){return entity;}}public record Source(Object owner,Object direct,String name){public Object getEntity(){return owner;}public Object getDirectEntity(){return direct;}public String getMsgId(){return name;}}public record Damage(Object entity,Source source,float amount){public Object getEntity(){return entity;}public Source getSource(){return source;}public float getNewDamage(){return amount;}}public static class Player{public Zombie.Point getEyePosition(){return new Zombie.Point(0,1.6,-2);}public Zombie.Point getViewVector(float f){return new Zombie.Point(0,0,1);}}public static class Bullet{public Object gunId="pistol";public int pierce;public Zombie.Point getDeltaMovement(){return new Zombie.Point(0,0,1);}}public record Hit(Zombie entity,Zombie.Point point,boolean head){public Object getEntity(){return entity;}public Object getLocation(){return point;}public boolean isHeadshot(){return head;}}static Zombie fresh(){Zombie z=new Zombie();Gore.define(new SynchedEntityData.Builder(z.data));return z;}
public static void main(String[]args){Gore.init();Zombie z=fresh();Gore.durability(new Event(z));check(z.getMaxHealth()==60&&z.getHealth()==60);Gore.durability(new Event(z));check(z.getMaxHealth()==60);Player p=new Player();Source melee=new Source(p,p,"player");z.hit=new Zombie.Point(0,1.8,0);Gore.hurt(new Damage(z,melee,1));check((Gore.state(z)&256)!=0&&(Gore.state(z)&1)==0);Gore.hurt(new Damage(z,melee,4));check((Gore.state(z)&1)!=0);Zombie legs=fresh();legs.hit=new Zombie.Point(.2,.4,0);Gore.hurt(new Damage(legs,melee,4));check((Gore.state(legs)&(1<<28))!=0);check(!Rules.crawling(Gore.state(legs))&&Rules.speed(Gore.state(legs))==.5);legs.hit=new Zombie.Point(-.2,.4,0);Gore.hurt(new Damage(legs,melee,4));check(Rules.crawling(Gore.state(legs))&&Rules.speed(Gore.state(legs))==.16);Zombie arms=fresh();arms.hit=new Zombie.Point(.4,1.2,0);Gore.hurt(new Damage(arms,melee,4));check((Rules.disabled(Gore.state(arms))&4)!=0&&Rules.attack(Gore.state(arms))==.6);arms.hit=new Zombie.Point(-.4,1.2,0);Gore.hurt(new Damage(arms,melee,4));check((Rules.disabled(Gore.state(arms))&12)==12&&Rules.attack(Gore.state(arms))==.45);Gore.hurt(new Damage(arms,melee,5));check((Gore.state(arms)&8)!=0);check(Rules.attack(Gore.state(arms)|2)==0);Bullet bullet=new Bullet();TimelessAPI.entries.put("pistol",new TimelessAPI.Index("pistol"));Zombie target=fresh();Gore.begin(bullet,new Hit(target,new Zombie.Point(0,1.2,0),false));Gore.hurt(new Damage(target,new Source(p,p,"compat"),2));Gore.end();check((Gore.state(target)&(1<<14))!=0);check(target.pushes==1);Zombie fallback=fresh();Gore.begin(bullet,new Hit(fallback,new Zombie.Point(0,1.2,0),false));fallback.health-=2;Gore.end();check((Gore.state(fallback)&(1<<14))!=0);Zombie blocked=fresh();Gore.begin(bullet,new Hit(blocked,new Zombie.Point(0,1.2,0),false));Gore.end();check(Gore.state(blocked)==0);int state=Rules.update(0,4,6,6,600,Rules.Weapon.SHOTGUN);check((state&16)!=0);check(Rules.zone(.75,0,true)==0);CompoundTag save=new CompoundTag();Gore.save(legs,save);Zombie copy=fresh();Gore.restore(copy,save);check(Gore.state(copy)==Gore.state(legs));Gore.registerVisuals();traben.entity_model_features.models.animation.state.EMFState.current=legs;check(traben.entity_model_features.models.animation.math.variables.VariableRegistry.INSTANCE.vars.get("zg_broken").get()==12);System.out.println("Progressive damage, melee, gun compatibility, durability and sync checks: "+n);}}
